query ResolveTeam($reference: String!, $id: ID, $isUuid: Boolean!) {
  teams(
    filter: {or: [{key: {eqIgnoreCase: $reference}}, {name: {eqIgnoreCase: $reference}}]}
  ) {
    nodes {
      id
      key
      name
    }
  }
  teamById: teams(filter: {id: {eq: $id}}) @include(if: $isUuid) {
    nodes {
      id
      key
      name
    }
  }
}

query LookupUser($input: String!) {
  users(
    filter: {or: [{email: {eqIgnoreCase: $input}}, {displayName: {eqIgnoreCase: $input}}, {name: {containsIgnoreCaseAndAccent: $input}}]}
  ) {
    nodes {
      id
      email
      displayName
      name
    }
  }
}

query GetIssueLabelIdByNameForTeam($name: String!, $teamKey: String!) {
  issueLabels(
    filter: {name: {eqIgnoreCase: $name}, or: [{team: {key: {eq: $teamKey}}}, {team: {null: true}}]}
  ) {
    nodes {
      id
      name
    }
  }
}
